import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'

interface Post {
  id: number
  title: string
  body: string
  userId: number
}

interface Comment {
  id: number
  name: string
  email: string
  body: string
  postId: number
}

interface BlogPostParams {
  id: string
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`)
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`
  )
  return res.json()
}

export const revalidate = 300 // 5 minutes

export async function generateStaticParams(): Promise<BlogPostParams[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts: Post[] = await res.json()

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: {
  params: Promise<BlogPostParams>
}): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)
  if (!post) {
    return { title: 'Post Not Found - My Blog' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({
  params,
}: {
  params: Promise<BlogPostParams>
}) {
  const { id } = await params

  const [post, comments] = await Promise.all([
    getPost(id),
    getComments(id),
  ])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <form action="">
        <button type="submit" formAction="javascript:history.back()">
          ← Back
        </button>
      </form>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

